INSERT OR IGNORE INTO icd10_im_entries (code,kind,title_extracted,source_file,source_sha256,pdf_page,review_status,raw_text,explicit_im_marker,entry_id) VALUES ('C66.9','diagnosis','Malignant neoplasm of unspecified ureter (IM)','list-of-icd-10im-terbaru_compress.pdf','40332b974ae46c3008b2dc14c698bb087c24d7f1559a300c53159ac834fdcaf3',9,'draft','C66.9    Malignant neoplasm of unspecified ureter (IM)



In situ neoplasms
         (D00-D09)
Note:
Many in situ neoplasms are regarded as being located within a continuum of morphological change
          between dysplasia and invasive cancer. For example, for cervical intraepithelial neoplasia
          (CIN) three grades are recognized, the third of which (CIN III) includes both severe
          dysplasia and carcinoma in situ. This system of grading has been extended to other organs,
          such as vulva and vagina. Descriptions of grade III intraepithelial neoplasia, with or without
          mention of severe dysplasia, are assigned to this section; grades I and II are classified as
          dysplasia of the organ system involved and should be coded to the relevant body system
          chapter.
Incl.:
Bowen disease
erythroplasia
morphology codes with behaviour code /2
Queyrat erythroplasia',1,'a56d63e579f2589cf531496b');
