INSERT OR IGNORE INTO icd10_im_entries (code,kind,title_extracted,source_file,source_sha256,pdf_page,review_status,raw_text,explicit_im_marker,entry_id) VALUES ('F45','diagnosis','Somatoform disorders','list-of-icd-10im-terbaru_compress.pdf','40332b974ae46c3008b2dc14c698bb087c24d7f1559a300c53159ac834fdcaf3',16,'draft','F45       Somatoform disorders',0,'2106a3d5f9627159efe252cf');
INSERT OR IGNORE INTO icd10_im_entries (code,kind,title_extracted,source_file,source_sha256,pdf_page,review_status,raw_text,explicit_im_marker,entry_id) VALUES ('F45.3','diagnosis','Somatoform autonomic dysfunction Symptoms are presented by the patient as if they were due to a physical disorder of a system or organ that is largely or completely under autonomic innervation and control, i.e. the cardiovascular, gastrointestinal, respiratory and urogenital systems. The symptoms are usually of two types, neither of which indicates a physical disorder of the organ or system concerned. First, there are complaints based upon objective signs of autonomic arousal, such as palpitations, sweating, flushing, tremor, and expression of fear and distress about the possibility of a physical disorder. Second, there are subjective complaints of a nonspecific or changing nature such as fleeting aches and pains, sensations of burning, heaviness, tightness, and feelings of being bloated or distended, which are referred by the patient to a specific organ or system. Cardiac neurosis Da Costa syndrome Gastric neurosis Neurocirculatory asthenia Psychogenic forms of:','list-of-icd-10im-terbaru_compress.pdf','40332b974ae46c3008b2dc14c698bb087c24d7f1559a300c53159ac834fdcaf3',16,'draft','F45.3    Somatoform autonomic dysfunction
Symptoms are presented by the patient as if they were due to a physical disorder of a system or
         organ that is largely or completely under autonomic innervation and control, i.e. the
         cardiovascular, gastrointestinal, respiratory and urogenital systems. The symptoms are
         usually of two types, neither of which indicates a physical disorder of the organ or system
         concerned. First, there are complaints based upon objective signs of autonomic arousal,
         such as palpitations, sweating, flushing, tremor, and expression of fear and distress about
         the possibility of a physical disorder. Second, there are subjective complaints of a
         nonspecific or changing nature such as fleeting aches and pains, sensations of burning,
         heaviness, tightness, and feelings of being bloated or distended, which are referred by the
         patient to a specific organ or system.
Cardiac neurosis
Da Costa syndrome
Gastric neurosis
Neurocirculatory asthenia
Psychogenic forms of:

•      aerophagy
•      cough
•      diarrhoea
•      dyspepsia
•      dysuria
•      flatulence
•      hiccough
•      hyperventilation
•      increased frequency of micturition
•      irritable bowel syndrome
•      pylorospasm
Excl.:
psychological and behavioural factors associated with disorders or diseases classified elsewhere
         (F54)',0,'5b8309f4426547d0c0774523');
INSERT OR IGNORE INTO icd10_im_entries (code,kind,title_extracted,source_file,source_sha256,pdf_page,review_status,raw_text,explicit_im_marker,entry_id) VALUES ('F45.39','diagnosis','Somatoform autonomic dysfunction, unspecified organ or system (IM)','list-of-icd-10im-terbaru_compress.pdf','40332b974ae46c3008b2dc14c698bb087c24d7f1559a300c53159ac834fdcaf3',17,'draft','F45.39 Somatoform autonomic dysfunction, unspecified organ or system (IM)',1,'ca7de47348f71a47827d5c89');
INSERT OR IGNORE INTO icd10_im_entries (code,kind,title_extracted,source_file,source_sha256,pdf_page,review_status,raw_text,explicit_im_marker,entry_id) VALUES ('F45.8','diagnosis','Other somatoform disorders Any other disorders of sensation, function and behaviour, not due to physical disorders, which are not mediated through the autonomic nervous system, which are limited to specific systems or parts of the body, and which are closely associated in time with stressful events or problems. Psychogenic:','list-of-icd-10im-terbaru_compress.pdf','40332b974ae46c3008b2dc14c698bb087c24d7f1559a300c53159ac834fdcaf3',17,'draft','F45.8    Other somatoform disorders
Any other disorders of sensation, function and behaviour, not due to physical disorders, which are not
         mediated through the autonomic nervous system, which are limited to specific systems or
         parts of the body, and which are closely associated in time with stressful events or
         problems.
Psychogenic:

•       dysmenorrhoea
•       dysphagia, including "globus hystericus"
•       pruritus
•       torticollis
Teeth-grinding',0,'f40c335c304b33f0355c1c05');
