       (F60-F69)',1,'a4ba8552b870a8ae2e71955e');
INSERT OR IGNORE INTO icd10_im_entries (code,kind,title_extracted,source_file,source_sha256,pdf_page,review_status,raw_text,explicit_im_marker,entry_id) VALUES ('F60','diagnosis','Specific personality disorders','list-of-icd-10im-terbaru_compress.pdf','40332b974ae46c3008b2dc14c698bb087c24d7f1559a300c53159ac834fdcaf3',17,'draft','F60       Specific personality disorders',0,'82c3fd0380d59da4485a2d49');
INSERT OR IGNORE INTO icd10_im_entries (code,kind,title_extracted,source_file,source_sha256,pdf_page,review_status,raw_text,explicit_im_marker,entry_id) VALUES ('F60.3','diagnosis','Emotionally unstable personality disorder Personality disorder characterized by a definite tendency to act impulsively and without consideration of the consequences; the mood is unpredictable and capricious. There is a liability to outbursts of emotion and an incapacity to control the behavioural explosions. There is a tendency to quarrelsome behaviour and to conflicts with others, especially when impulsive acts are thwarted or censored. Two types may be distinguished: the impulsive type, characterized predominantly by emotional instability and lack of impulse control, and the borderline type, characterized in addition by disturbances in self-image, aims, and internal preferences, by chronic feelings of emptiness, by intense and unstable interpersonal relationships, and by a tendency to self-destructive behaviour, including suicide gestures and attempts. Personality (disorder):','list-of-icd-10im-terbaru_compress.pdf','40332b974ae46c3008b2dc14c698bb087c24d7f1559a300c53159ac834fdcaf3',17,'draft','F60.3    Emotionally unstable personality disorder
Personality disorder characterized by a definite tendency to act impulsively and without consideration
         of the consequences; the mood is unpredictable and capricious. There is a liability to
         outbursts of emotion and an incapacity to control the behavioural explosions. There is a
         tendency to quarrelsome behaviour and to conflicts with others, especially when impulsive
         acts are thwarted or censored. Two types may be distinguished: the impulsive type,
         characterized predominantly by emotional instability and lack of impulse control, and the
         borderline type, characterized in addition by disturbances in self-image, aims, and internal
         preferences, by chronic feelings of emptiness, by intense and unstable interpersonal
         relationships, and by a tendency to self-destructive behaviour, including suicide gestures
         and attempts.
Personality (disorder):

•       aggressive
•       borderline
•       explosive
